 then KO[#KO+1]=MR(MH(KV/16777216)%256,MH(KV/65536)%256,MH(KV/256)%256,KV%256);KV=0;KN=0 end end;if KN>1 then local KI=5-KN;while KI>0 do KV=KV*85+84;KI=KI-1 end;local KD=MR(MH(KV/16777216)%256,MH(KV/65536)%256,MH(KV/256)%256,KV%256);KO[#KO+1]=Mw(KD,1,KN-1)elseif KN==1 then return nil end;return table.concat(KO)end;local B,H=game:GetService("EncodingService"),Enum.CompressionAlgorithm.Zstd;local F=Mm.tostring(B:DecompressBuffer(Mm.fromstring(L(J[730471])),H));local Mb=(MV(F,4)+MV(F,3)*256+MV(F,2)*65536+MV(F,1)*16777216-2686460627)%4294967296;local Mq=(MV(F,8)+MV(F,7)*256+MV(F,6)*65536+MV(F,5)*16777216-3952316868)%4294967296;local MM=9;local MB=Mw(F,MM,MM+Mb-1);MM=MM+Mb;local MX=Mw(F,MM,MM+Mq-1);MM=MM+Mq;return loadstring(MX)(MB,...)end}):D(...)
